        vm.assume(newSettings != address(0));
        c.initialize();
        c.renounceOwnership();
        address actualOwnerBefore = c.owner();
        vm.prank(operator);
        try c.renounceOwnership() { } catch { }
        try c.transferOwnership(operator) { } catch { }
        vm.prank(operator);
        try c.updateAlloSettings(newSettings) { } catch { }
        vm.prank(operator);
        try c.updateRoundImplementation(payable(newSettings)) { } catch { }
