pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.initialize();
    }

    function testFuzz_property(address ownerEOA, address unrelatedCaller, uint96 dummyBalance) public {
        // 1. Bound to plausible EOA range and avoid address collisions
        vm.assume(ownerEOA != address(0));
        vm.assume(unrelatedCaller != address(0));
        vm.assume(ownerEOA != unrelatedCaller);
        vm.assume(ownerEOA != address(c));
        vm.assume(unrelatedCaller != address(c));
        // Keep addresses as EOAs (no code)
        vm.assume(ownerEOA.code.length == 0);
        vm.assume(unrelatedCaller.code.length == 0);

        // 2. Set up: transfer ownership to ownerEOA
        vm.prank(address(this)); // msg.sender is the test contract, which is the current owner after initialize
        c.transferOwnership(ownerEOA);

        // Record owner reported by ownerEOA
        vm.prank(ownerEOA);
        address ownerReportedByEOA = c.owner();

        // 3. Assert: the address returned by c.owner() when called by any EOA that is NOT the actual owner
        // must NOT equal the caller's own address. The correct contract returns the stored _owner (ownerEOA),
        // while the buggy one returns msg.sender (unrelatedCaller).
        vm.prank(unrelatedCaller);
        address ownerReportedByUnrelated = c.owner();

        assertTrue(
            ownerReportedByUnrelated == ownerEOA && ownerReportedByEOA == ownerEOA,
            "owner() must return the stored owner regardless of caller"
        );
    }
}

