import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.initialize();
    }
    function testFuzz_property(address fuzzOwner) public {
        vm.assume(fuzzOwner != address(0));
        // Transfer ownership to fuzzOwner to set the private _owner state
        vm.prank(address(this));
        c.transferOwnership(fuzzOwner);

        // Check that owner() returns the address that was just set
        address currentOwner = c.owner();

        // Assert that the owner returned is the one we set, not a constant like address(1)
        assertTrue(currentOwner == fuzzOwner);
    }
}

