import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(address newOwner, uint8 initCall) public {
        vm.assume(newOwner != address(0));
        // Ensure initialization occurs at most once
        if (initCall % 2 == 0) {
            c.initialize();
        }
        address originalOwner = address(this);
        vm.prank(originalOwner);
        c.transferOwnership(newOwner);
        // attempt to transfer to zero via the buggy path
        vm.prank(newOwner);
        bool ok = true;
        try c.transferOwnership(address(0)) {
            ok = true;
        } catch {
            ok = false;
        }
        assertTrue(c.owner() != address(0) || !ok);
    }
}

