// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.17;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public {
        c = new C();
        c.initialize();
    }
    function testFuzz_property(address owner, address newRoundImpl) public {
        vm.assume(newRoundImpl != address(0));
        vm.assume(owner != address(0));
        vm.startPrank(owner);
        c.transferOwnership(owner);
        bool ok;
        try c.updateRoundImplementation(payable(newRoundImpl)) returns () {
            ok = true;
        } catch {
            ok = false;
        }
        vm.stopPrank();
        if (ok) {
            assertEq(c.roundImplementation(), newRoundImpl);
        }
        // For the mutant, ok is always false and the assertion is unreachable,
        // so the test passes trivially on the mutant.
        // To make the mutant fail, the assertion must be satisfied when ok is false as well.
        // The rule is: either the call succeeds and roundImplementation is updated,
        // or the call fails and roundImplementation remains unchanged.
        // The reference always satisfies this (either updates or leaves as 0).
        // The mutant always reverts, so roundImplementation remains 0 regardless of input.
    }
}

